const About = () => {
    return (
        <div className="about">
            <h1>About Me</h1>
            <p>
                Welcome to my portfolio! I am [Your Name], a [Your Profession/Title] with a passion for [Your Interests/Skills]. 
                I have experience in [Your Experience/Background] and have worked on various projects that showcase my abilities in [Your Skills].
            </p>
            <h2>Skills</h2>
            <ul>
                <li>[Skill 1]</li>
                <li>[Skill 2]</li>
                <li>[Skill 3]</li>
                <li>[Skill 4]</li>
            </ul>
            <h2>Background</h2>
            <p>
                I have a background in [Your Background Information]. My journey in [Your Field/Industry] has been [Brief Description of Your Journey].
            </p>
        </div>
    );
};

export default About;
